<div class="metrics"><div class="metric"><span><?= e(t('Total balance to pay')) ?></span><strong><?= e(money(array_sum(array_column($rows,'balance')))) ?> <small><?= e(t('MMK')) ?></small></strong><small><?= e(t('Across all suppliers')) ?></small></div><div class="metric"><span><?= e(t('Suppliers with credit')) ?></span><strong><?= count(array_filter($rows,fn($r)=>(float)$r['balance']>0)) ?></strong><small><?= e(t('Outstanding accounts')) ?></small></div><div class="metric"><span><?= e(t('Later payments recorded')) ?></span><strong><?= e(money(array_sum(array_column($rows,'payments_total')))) ?> <small><?= e(t('MMK')) ?></small></strong><small><?= e(t('Supplier settlements')) ?></small></div></div>
<section class="panel"><div class="panel-heading"><div><div class="eyebrow"><?= e(t('ACCOUNTS PAYABLE')) ?></div><h2><?= e(t('Supplier balances')) ?></h2></div><?php if(can('settings.manage')): ?><a class="button" href="<?= e(url('suppliers')) ?>"><?= e(t('Manage suppliers')) ?></a><?php endif; ?></div><div class="table-wrap"><table><thead><tr><th><?= e(t('Supplier')) ?></th><th class="number"><?= e(t('Purchases (MMK)')) ?></th><th class="number"><?= e(t('Paid at purchase')) ?></th><th class="number"><?= e(t('Later payments')) ?></th><th class="number"><?= e(t('Balance to pay')) ?></th><th><?= e(t('Status')) ?></th><th class="table-actions"><?= e(t('Actions')) ?></th></tr></thead><tbody><?php foreach($rows as $row): ?><tr><td><strong><?= e($row['name']) ?></strong><small><?= e($row['phone']) ?></small></td><td class="number"><?= e(money($row['purchase_total'])) ?></td><td class="number"><?= e(money($row['purchase_paid'])) ?></td><td class="number"><?= e(money($row['payments_total'])) ?></td><td class="number"><strong><?= e(money($row['balance'])) ?></strong></td><td><span class="badge <?= (float)$row['balance']>0?'production':'purchase' ?>"><?= (float)$row['balance']>0?t('To pay'):t('Settled') ?></span></td><td class="table-actions"><a class="button small" href="<?= e(url('suppliers/'.$row['id'].'/credit')) ?>"><?= e(t('View / Pay')) ?></a></td></tr><?php endforeach; ?><?php if(!$rows): ?><tr><td colspan="7" class="empty"><?= e(t('No suppliers yet. Add suppliers to start tracking credit.')) ?></td></tr><?php endif; ?></tbody></table></div></section>
